// Extract dataset URLs from metadata
const datasets = [];

for (const item of $input.all()) {
  const data = item.json;

  // Extract Items array from metadata response
  const items = data.Items || data.items || [];

  for (const dataset of items) {
    if (dataset.ApiUrl || dataset.apiUrl) {
      datasets.push({
        url: dataset.ApiUrl || dataset.apiUrl,
        name: dataset.Shortname || dataset.shortname || dataset.Id || 'Unknown'
      });
    }
  }
}

return datasets.map(d => ({ json: d }));

// Accumulate records and check pagination
const currentData = $input.first().json;
const existingRecords = $('Initialize Variables').first().json.allRecords;

// Extract records from response
let newRecords = [];
if (Array.isArray(currentData)) {
  newRecords = currentData;
} else if (currentData.Items) {
  newRecords = currentData.Items;
} else if (currentData.items) {
  newRecords = currentData.items;
}

// Combine with existing
const allRecords = [...existingRecords, ...newRecords];

// Check if more pages exist
const totalResults = currentData.TotalResults || currentData.totalResults || 0;
const currentPage = $('Initialize Variables').first().json.page;
const hasMore = allRecords.length < totalResults && newRecords.length > 0;

return [{
  json: {
    url: $('Initialize Variables').first().json.url,
    name: $('Initialize Variables').first().json.name,
    page: currentPage + 1,
    allRecords,
    hasMore
  }
}];

// Use the exact same analysis logic from your existing workflow
// Copy-pasted from "Dashboard Creation" node

let rawRecords = $json.allRecords;

if (!rawRecords.length) {
  return [{ json: { error: 'No records found', url: $json.url } }];
}

function flattenObject(obj, prefix = '') {
  const result = {};
  for (const [key, value] of Object.entries(obj)) {
    const newKey = prefix ? `${prefix}.${key}` : key;
    if (value === null || value === undefined) {
      result[newKey] = null;
    } else if (Array.isArray(value)) {
      result[newKey] = value;
    } else if (typeof value === 'object') {
      Object.assign(result, flattenObject(value, newKey));
    } else {
      result[newKey] = value;
    }
  }
  return result;
}

const flattenedData = rawRecords.map(r => flattenObject(r));
const totalRecords = flattenedData.length;

const completenessByField = {};
const consistencyMetrics = {};
const statisticalMetrics = {};
const allFields = new Set();

for (const record of flattenedData) {
  Object.keys(record).forEach(f => allFields.add(f));
}

for (const field of allFields) {
  let presentCount = 0;
  let missingCount = 0;
  const typeCounts = {};
  const numericValues = [];

  for (const record of flattenedData) {
    const v = record[field];

    if (v === null || v === undefined || (typeof v === 'string' && v.trim() === '')) {
      missingCount++;
    } else {
      presentCount++;
      const type = Array.isArray(v) ? 'array' : typeof v;
      typeCounts[type] = (typeCounts[type] || 0) + 1;

      if (type === 'number' && isFinite(v)) {
        numericValues.push(v);
      }
    }
  }

  const presentPercentage = Number((presentCount / totalRecords * 100).toFixed(2));
  const missingPercentage = Number((missingCount / totalRecords * 100).toFixed(2));
  const types = Object.keys(typeCounts);
  const dominantType = types[0] || 'unknown';
  const dominantCount = Math.max(...Object.values(typeCounts), 0);
  const totalNonNull = presentCount;
  const consistencyPercentage = totalNonNull > 0 ? Number((dominantCount / totalNonNull * 100).toFixed(2)) : 100;
  const isConsistent = types.length <= 1;

  completenessByField[field] = {
    field,
    presentPercentage,
    missingPercentage,
    presentCount,
    missingCount,
    dataType: dominantType
  };

  consistencyMetrics[field] = {
    field,
    dominantType,
    dataTypesFound: types,
    consistencyPercentage,
    isConsistent
  };

  if (numericValues.length > 0) {
    const sum = numericValues.reduce((s, x) => s + x, 0);
    const mean = sum / numericValues.length;
    const min = Math.min(...numericValues);
    const max = Math.max(...numericValues);
    statisticalMetrics[field] = {
      field,
      mean: Number(mean.toFixed(2)),
      min: Number(min.toFixed(2)),
      max: Number(max.toFixed(2)),
      count: numericValues.length
    };
  }
}

const totalCells = totalRecords * allFields.size;
const totalPresentCount = Object.values(completenessByField).reduce((s, f) => s + f.presentCount, 0);
const overallCompleteness = Number((totalPresentCount / totalCells * 100).toFixed(2));
const criticalFieldsCount = Object.values(completenessByField).filter(f => f.presentPercentage < 50).length;
const consistentFieldsCount = Object.values(consistencyMetrics).filter(f => f.isConsistent).length;
const overallConsistency = Number((consistentFieldsCount / allFields.size * 100).toFixed(2));

const recordMap = new Map();
for (const record of flattenedData) {
  const key = JSON.stringify(record);
  recordMap.set(key, (recordMap.get(key) || 0) + 1);
}
const duplicateRecords = Array.from(recordMap.values()).filter(c => c > 1).length;
const uniquenessScore = Number(Math.max(0, 100 - ((duplicateRecords / totalRecords) * 100)).toFixed(2));

const overallQualityScore = Number((
  overallCompleteness * 0.4 +
  overallConsistency * 0.3 +
  uniquenessScore * 0.2 +
  overallConsistency * 0.1
).toFixed(2));

const completenessArray = Object.values(completenessByField);
const fieldCompleteness = completenessArray
  .sort((a, b) => b.missingPercentage - a.missingPercentage)
  .map(f => ({
    name: f.field,
    completeness: f.presentPercentage,
    missing: f.missingPercentage,
    dataType: f.dataType,
    presentCount: f.presentCount,
    missingCount: f.missingCount
  }));

const kpis = {
  qualityScore: overallQualityScore,
  totalRecords,
  totalFields: allFields.size,
  completenessScore: overallCompleteness,
  consistencyScore: overallConsistency,
  uniquenessScore,
  validityScore: overallConsistency,
  criticalFields: criticalFieldsCount
};

const qualityScores = [
  { dimension: 'Completeness', score: overallCompleteness },
  { dimension: 'Consistency', score: overallConsistency },
  { dimension: 'Uniqueness', score: uniquenessScore },
  { dimension: 'Validity', score: overallConsistency }
];

const typeCountMap = {};
for (const metric of Object.values(consistencyMetrics)) {
  typeCountMap[metric.dominantType] = (typeCountMap[metric.dominantType] || 0) + 1;
}
const dataTypeDistribution = Object.entries(typeCountMap).map(([name, value]) => ({ name, value }));

const bucketCounts = [0, 0, 0, 0, 0];
for (const f of completenessArray) {
  const pct = f.presentPercentage;
  if (pct <= 20) bucketCounts[0]++;
  else if (pct <= 40) bucketCounts[1]++;
  else if (pct <= 60) bucketCounts[2]++;
  else if (pct <= 80) bucketCounts[3]++;
  else bucketCounts[4]++;
}

const completenessDistribution = [
  { range: '0-20%', count: bucketCounts[0] },
  { range: '21-40%', count: bucketCounts[1] },
  { range: '41-60%', count: bucketCounts[2] },
  { range: '61-80%', count: bucketCounts[3] },
  { range: '81-100%', count: bucketCounts[4] }
];

return [{
  json: {
    url: $json.url,
    name: $json.name,
    cachedAt: new Date().toISOString(),
    results: {
      kpis,
      fieldCompleteness,
      qualityScores,
      dataTypeDistribution,
      completenessDistribution
    }
  }
}];
